insert into public.wuku (urutan, nama, dewa, watak, sumber) values
  (0, 'Sinta', 'Batara Yamadipati', 'Terlihat bijak dan berambisi. Awalnya lembut lalu bisa jadi keras, agak keras kepala, dan mudah stres.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (1, 'Landep', 'Batara Mahadewa', 'Rupawan, tenang, dan ceria. Tegas di awal lalu melunak, tetapi suka memamerkan apa yang dimiliki.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (2, 'Wukir', 'Batara Mahayekti', 'Berjiwa besar, dermawan, dan berbakat seni, tetapi wataknya sulit dipahami orang.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (3, 'Kurantil', 'Batara Langsur', 'Pandai mengambil hati orang dan teguh pendirian, tetapi boros sehingga rezekinya naik-turun.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (4, 'Tolu', 'Batara Bayu', 'Lugas dan menyenangkan, tetapi bisa sombong dan cepat marah. Keberuntungannya datang di hari tua.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (5, 'Gumbreg', 'Batara Cakra', 'Kemauannya keras, jujur, dan murah hati. Melindungi keluarga, tetapi suka berdebat.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (6, 'Warigalit', 'Batara Asmara', 'Menawan dan digemari, tetapi pencemburu, mudah jatuh cinta, dan suka menyendiri.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (7, 'Warigagung', 'Batara Maharesi', 'Bertanggung jawab dan dipercaya orang, pandai bicara, dan tegas dalam ucapan.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (8, 'Julungwangi', 'Batara Sambu', 'Dermawan dan pandai meyakinkan orang, tetapi agak angkuh dan mudah bosan sehingga kadang ingkar janji.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (9, 'Sungsang', 'Batara Gana', 'Cerdas, kuat, dan dermawan, tetapi cenderung boros dan kadang menginginkan milik orang lain.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (10, 'Galungan', 'Batara Kamajaya', 'Berwajah menarik, tulus, dan suka memberi, tetapi temperamental dan senang bersaing.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (11, 'Kuningan', 'Batara Indra', 'Berbudi luhur, berwibawa, teliti, dan hemat, tetapi pemalu dan kadang kurang terus terang.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (12, 'Langkir', 'Batara Kala', 'Berani, tetapi keras kepala dan sulit didekati. Banyak bicara namun kurang bertindak.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (13, 'Mandasiya', 'Batara Brahma', 'Tegas, punya harga diri tinggi, sabar, dan melindungi orang lain, tetapi sulit meredam amarah.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (14, 'Julungpujut', 'Batara Guritna', 'Suka keramaian dan sopan, berambisi besar, tetapi usahanya sering kurang membuahkan hasil.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (15, 'Pahang', 'Batara Tantra', 'Berwibawa dan disegani, pendiam, dan gigih, dengan ambisi yang disimpan rapat.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (16, 'Kuruwelut', 'Batara Wisnu', 'Supel, cermat, dan disukai banyak orang, tetapi mudah percaya sehingga gampang dimanfaatkan.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (17, 'Marakeh', 'Batara Surenggana', 'Pendiam dan halus perasaannya, tekun, berintuisi tajam, dan selalu berhati-hati.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (18, 'Tambir', 'Batara Siwa', 'Pemikir yang tenang dan spiritual. Lebih suka bekerja di balik layar, tetapi hasilnya nyata.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (19, 'Medangkungan', 'Batara Basuki', 'Tangguh, pekerja keras, dan setia. Mampu memimpin kelompok kecil dan lembut kepada orang terdekat.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (20, 'Maktal', 'Batara Sakri', 'Gigih, berwibawa, santun, dan disayangi atasan, tetapi suka menyendiri dan rawan berselisih.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (21, 'Wuye', 'Batara Kuwera', 'Pandai memikat dan meyakinkan, kuat, dan waspada, tetapi mudah marah dan kadang cemburu.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (22, 'Manahil', 'Batara Citragotra', 'Pandai bergaul, praktis, dan hemat, tetapi sering disalahpahami dan kadang agak malas.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (23, 'Prangbakat', 'Batara Bisma', 'Tegas dan terampil, beruntung dan panjang umur, tetapi agak kaku, pemalu, dan kadang congkak.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (24, 'Bala', 'Batari Durga', 'Dekat dengan orang berpengaruh, tetapi suka membuat keributan dan rezekinya tidak menentu.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (25, 'Wugu', 'Batara Singajalma', 'Lapang dada, bijak, rendah hati, dan rezekinya lancar, tetapi kadang tanpa sadar mengecewakan orang dekat.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (26, 'Wayang', 'Batari Sri', 'Menawan, peka perasaan orang, teliti, sabar, dan dermawan, tetapi ada sisi suka menyendiri.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (27, 'Kulawu', 'Batara Sadana', 'Berani, murah hati, teguh, dan riang, tetapi kurang memperhitungkan risiko. Dipercaya berumur panjang.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (28, 'Dukut', 'Batara Baruna', 'Disiplin dan keras seperti prajurit, cerdas, dan setia, tetapi bisa tamak sehingga kurang disukai.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.'),
  (29, 'Watugunung', 'Batara Anantaboga', 'Banyak keinginan, suka berdebat, religius, dan romantis, tetapi cenderung menyendiri.', 'detikJateng, "30 Nama Wuku dalam Kalender Jawa Beserta Arti dan Cara Menghitungnya" (30 Mei 2025), merujuk Horoskop Jawa (Suroso Aji Pamungkas) dan Primbon Masa Kini. Teks diparafrasakan.');
